      "set.privacy.export": "laadi andmete koopia alla", "set.privacy.lock": "lukk", "set.privacy.lockOff": "Seadmata: kõik, mida kirjutad, on selles seadmes avatult.", "set.privacy.lockOnIdle": "Seatud. Lukustub ise {n} min pärast, kui sind pole.", "set.privacy.lockOnNoIdle": "Seatud. Ise ei lukustu — ainult siis, kui sina lukustad.", "set.privacy.lockCant": "Siin võimatu: brauser annab päris krüptograafia ainult üle https.", "set.privacy.lockOpen": "ava lukk", "set.privacy.copies": "koopiad", "set.privacy.copiesNone": "Kausta pole valitud — ükski koopia ei lahku sellest brauserist.", "set.privacy.copiesFolder": "Kaust „{name}“.", "set.privacy.copiesLast": "Viimane koopia: {when}.", "set.privacy.copiesNever": "Veel pole midagi kirjutatud.", "set.privacy.copiesCant": "See brauser ei oska kausta kirjutada — jääb fail, mille laadid ise alla.", "set.privacy.copiesOpen": "ava koopiad",
