      "set.about.build": "versioon",
      "set.about.madeOf": "millest tehtud",
      "set.about.madeOfValue": "HTML, CSS ja JavaScript — ilma võõra koodita",
      "set.about.runsOn": "kus töötab",
      "set.about.runsOnValue": "ainult selles brauseris — serveripoolt pole, midagi pole installitud",
      "set.about.data": "teie andmed",
      "set.about.dataValue": "{count} kohalikku võtit", "set.about.dataValue.one": "{count} kohalik võti", "set.about.dataValue.few": "{count} kohalikku võtit",
      "set.about.network": "võrk",
      "set.about.networkValue": "süsteem ise ei tee ühtegi — ei analüütikat, ei jälgimist, ei kõnet koju. Brauseris avatud lehed suhtlevad oma saitidega.",
      "set.about.languages": "keeled",
      "set.about.whatTitle": "mis see töölaud on",
      "set.about.whatBody": "Töötav vastus ühele küsimusele: milline on tunne, kui tarkvara kuulub teile? Iga tuba siin on päris — märkmed püsivad, failid liiguvad — ja kõik see töötab teie seadmes.",
      "set.about.whoTitle": "kes seda ehitab",
      "set.about.openBuild": "ava build", "set.about.whoBody": "Süsteemistuudio Tallinnas. Töölaua, mida te praegu vaatate, on kirjutanud samad käed, mis ehitavad kliendisüsteeme — see on meie töö tõend, mitte mall. Oma projekti alustamiseks avage {build}.",
      "set.about.note": "Profiilid elavad siin selles brauseris, mitte serveris. Miski ei lahku, kui te ise koopiat ei tee.",
      "set.about.doorTitle": "üks uks",
      "set.about.doorBody": "Teie süsteemil on üks uks ja see on suletud isegi meie jaoks.\nMeil on samuti üks uks — {door}. See on teile avatud.\nMe ei näe teie süsteemi ega küsi kunagi teie sõna.\nKirjeldage, mida näete.",
      "set.about.doorMailSubject": "Mida ma näen",
      "set.about.doorMailBody": "\n\n\n—\nversioon: {build}\nbrauser: {browser}\nkeel: {lang}\nNeed kolm rida võite kustutada — need aitavad meil ainult leida, mida te näete.",
